  assert.equal(await totalOf([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 1 }]), 80)
})

test('total: threshold is strict, exactly 100 gets no discount', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 100)
})

