  assert.equal(await totalOf([{ sku: 'A', qty: 5 }]), 135)
  assert.equal(await totalOf([{ sku: 'G', qty: 3 }]), 2700)
})

test('total: fractional prices are floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor truncates cents; 33.33*2=66.66 becomes 66.
  assert.equal(await totalOf([{ sku: 'E', qty: 2 }]), 66)
  // CHARACTERIZATION: current behaviour may be unintended — 33.33*4=133.32, -10% = 119.988 becomes 119.
  assert.equal(await totalOf([{ sku: 'E', qty: 4 }]), 119)
})

test('total: floating point sums (0.1 * 3)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — money computed with floats.
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 0)
})

test('total: missing qty yields a null total (NaN serialised), not a 400', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated.
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('total: negative qty is accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated.
  assert.equal(await totalOf([{ sku: 'A', qty: -1 }]), -30)
})

test('POST /orders: 400 for missing, empty, non-array items and invalid JSON', async () => {
